import { useState } from 'react'

function errorsFor(amount: string, card: string, expiry: string, cvc: string) {
  const errors: Record<string, string> = {}
  if (!/^\d+(\.\d{1,2})?$/.test(amount) || Number(amount) <= 0) errors.amount = 'Enter an amount like 25.00'
  if (card.replace(/\s/g, '').length < 12) errors.card = 'Card number looks too short'
  if (!/^(0[1-9]|1[0-2])\/\d{2}$/.test(expiry)) errors.expiry = 'Use MM/YY'
  if (!/^\d{3,4}$/.test(cvc)) errors.cvc = 'CVC is 3 or 4 digits'
  return errors
}

export function CheckoutForm({ onPaid }: { onPaid: (id: string) => void }) {
  const [amount, setAmount] = useState('')
  const [card, setCard] = useState('')
  const [expiry, setExpiry] = useState('')
  const [cvc, setCvc] = useState('')
  const [submitted, setSubmitted] = useState(false)
  const errors = errorsFor(amount, card, expiry, cvc)

  async function submit(e: React.FormEvent) {
    e.preventDefault()
    setSubmitted(true)
    if (Object.keys(errors).length) return
    const res = await fetch('/payments/charge', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ amountCents: Math.round(Number(amount) * 100), currency: 'CAD', cardToken: 'pm_card_visa' }),
    })
    const body = await res.json()
    if (body.ok) onPaid(body.id)
  }

  return (
    <form className='checkout' onSubmit={submit} noValidate>
      <label>Amount <input value={amount} onChange={(e) => setAmount(e.target.value)} /></label>
      {submitted && errors.amount && <p className='error'>{errors.amount}</p>}
      <label>Card number <input value={card} onChange={(e) => setCard(e.target.value)} /></label>
      {submitted && errors.card && <p className='error'>{errors.card}</p>}
      <label>Expiry <input value={expiry} placeholder='MM/YY' onChange={(e) => setExpiry(e.target.value)} /></label>
      {submitted && errors.expiry && <p className='error'>{errors.expiry}</p>}
      <label>CVC <input value={cvc} onChange={(e) => setCvc(e.target.value)} /></label>
      {submitted && errors.cvc && <p className='error'>{errors.cvc}</p>}
      <button type='submit'>Pay</button>
    </form>
  )
}

